sksl:
uniform shader image;
uniform shader palette;
uniform shader thresholds;
uniform float2 size;
uniform float time;
uniform float source;
uniform float colors;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
layout(color) uniform half4 color3;
layout(color) uniform half4 color4;
layout(color) uniform half4 color5;
layout(color) uniform half4 color6;
layout(color) uniform half4 color7;
layout(color) uniform half4 color8;
uniform float pattern;
uniform float dither;
uniform float alpha;
uniform float paletteSize;
uniform float paletteSpread;
uniform half4 swatches[16];
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float3 lookup(float3 c) {
    c = clamp(c, 0.0, 1.0);
    if (paletteSize < 16.5) {
        float3 best = float3(0.0);
        float bestD = 100.0;
        for (int i = 0; i < 16; i++) {
            if (float(i) >= paletteSize) break;
            float3 s = float3(swatches[i].rgb);
            float d = dot(c - s, c - s);
            if (d < bestD) { bestD = d; best = s; }
        }
        return best;
    }
    float3 q = floor(c * 31.0 + 0.5);
    return float3(palette.eval(float2(mod(q.b, 8.0) * 32.0 + q.r + 0.5, floor(q.b / 8.0) * 32.0 + q.g + 0.5)).rgb);
}
float3 nearest(float3 rgb) {
    float3 best = float3(color1.rgb);
    float bestD = distance(rgb, best);
    float d = distance(rgb, float3(color2.rgb));
    if (d < bestD) { bestD = d; best = float3(color2.rgb); }
    if (colors > 2.5) { d = distance(rgb, float3(color3.rgb)); if (d < bestD) { bestD = d; best = float3(color3.rgb); } }
    if (colors > 3.5) { d = distance(rgb, float3(color4.rgb)); if (d < bestD) { bestD = d; best = float3(color4.rgb); } }
    if (colors > 4.5) { d = distance(rgb, float3(color5.rgb)); if (d < bestD) { bestD = d; best = float3(color5.rgb); } }
    if (colors > 5.5) { d = distance(rgb, float3(color6.rgb)); if (d < bestD) { bestD = d; best = float3(color6.rgb); } }
    if (colors > 6.5) { d = distance(rgb, float3(color7.rgb)); if (d < bestD) { bestD = d; best = float3(color7.rgb); } }
    if (colors > 7.5) { d = distance(rgb, float3(color8.rgb)); if (d < bestD) { bestD = d; best = float3(color8.rgb); } }
    return best;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = base;
    if (pattern > 0.5 && pattern < 1.5) rgb += (hash12(floor(coord)) - 0.5) * dither * 0.3;
    else if (pattern > 1.5) rgb += (float(thresholds.eval(floor(coord) + 0.5).r) - 0.5) * dither * paletteSpread;
    float3 best = source > 0.5 ? lookup(rgb) : nearest(rgb);
    return half4(half3(mix(base, best, clamp(alpha, 0.0, 1.0))) * src.a, src.a);
}
